package com.siiiweb.project.controller;import com.siiiweb.project.entity.ProjectItem;import com.siiiweb.project.repository.ProjectRepository;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController public class ProjectController{private final ProjectRepository repo;public ProjectController(ProjectRepository r){repo=r;}@GetMapping("/api/projects") public List<ProjectItem> list(){return repo.findAll();}@PostMapping("/api/admin/projects") public ProjectItem create(@RequestBody ProjectItem p){return repo.save(p);}@PutMapping("/api/admin/projects/{id}") public ProjectItem update(@PathVariable Long id,@RequestBody ProjectItem p){p.id=id;return repo.save(p);}@DeleteMapping("/api/admin/projects/{id}") public void del(@PathVariable Long id){repo.deleteById(id);}}
